    async Task<long> IFaturaSaneamentoRepository.GerarPorLeituraAsync(long t,long e,long? ex,long leituraId,long? u,GerarFaturaPorLeituraRequest r,string numero,string ambiente,CancellationToken ct){using var cn=_context.CreateConnection(); const string sql="insert into sigov.saneamento_fatura(tenant_id,entidade_id,exercicio_id,unidade_consumidora_id,leitura_id,numero,competencia,data_vencimento,valor_agua,valor_esgoto,valor_servicos,valor_total,status,codigo_barras,linha_digitavel,ambiente,created_by) select tenant_id,entidade_id,@ExercicioId,unidade_consumidora_id,id,@Numero,competencia,@DataVencimento,consumo_faturado*@TarifaAgua,consumo_faturado*@TarifaEsgoto,@ValorServicos,(consumo_faturado*@TarifaAgua)+(consumo_faturado*@TarifaEsgoto)+@ValorServicos,'ABERTA',@Codigo,@Linha,@Ambiente,@UsuarioId from sigov.saneamento_leitura where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@LeituraId and is_deleted=false returning id"; return await cn.ExecuteScalarAsync<long>(new CommandDefinition(sql,new{TenantId=t,EntidadeId=e,ExercicioId=ex,LeituraId=leituraId,Numero=numero,r.DataVencimento,r.TarifaAgua,r.TarifaEsgoto,r.ValorServicos,Codigo=$"FAKE-{numero}",Linha=$"DEV-{numero}",Ambiente=ambiente,UsuarioId=u},cancellationToken:ct));}
