    async Task<ArrecadacaoSaneamentoResponse> IFaturaSaneamentoRepository.RegistrarPagamentoDevAsync(long t,long e,long? ex,long id,long? u,RegistrarPagamentoDevRequest r,string numero,CancellationToken ct){using var cn=_context.CreateConnection(); cn.Open(); using var tx=cn.BeginTransaction(); var f=await cn.QuerySingleAsync<(decimal ValorTotal,decimal ValorPago,string Status)>(new CommandDefinition("select valor_total as ValorTotal,valor_pago as ValorPago,status as Status from sigov.saneamento_fatura where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id and is_deleted=false for update",new{TenantId=t,EntidadeId=e,Id=id},transaction:tx,cancellationToken:ct)); if(f.Status is "PAGA" or "CANCELADA") throw new InvalidOperationException("Fatura não pode receber pagamento."); if(r.ValorPago<=0 || r.ValorPago>f.ValorTotal-f.ValorPago) throw new InvalidOperationException("Pagamento inválido para o saldo da fatura."); var aid=await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.saneamento_arrecadacao(tenant_id,entidade_id,exercicio_id,fatura_id,numero,data_pagamento,forma_pagamento,valor_pago,origem,metadados,created_by) values(@TenantId,@EntidadeId,@ExercicioId,@FaturaId,@Numero,@DataPagamento,'MANUAL_DEV',@ValorPago,@Origem,'{}'::jsonb,@UsuarioId) returning id",new{TenantId=t,EntidadeId=e,ExercicioId=ex,FaturaId=id,Numero=numero,DataPagamento=r.DataPagamento??DateOnly.FromDateTime(DateTime.UtcNow),r.ValorPago,r.Origem,UsuarioId=u},transaction:tx,cancellationToken:ct)); var novo=f.ValorPago+r.ValorPago; await cn.ExecuteAsync(new CommandDefinition("update sigov.saneamento_fatura set valor_pago=@ValorPago,status=case when @ValorPago>=valor_total then 'PAGA' else status end,updated_at=now(),updated_by=@UsuarioId where tenant_id=@TenantId and entidade_id=@EntidadeId and id=@Id",new{TenantId=t,EntidadeId=e,Id=id,ValorPago=novo,UsuarioId=u},transaction:tx,cancellationToken:ct)); tx.Commit(); return new(aid,id,numero,r.DataPagamento??DateOnly.FromDateTime(DateTime.UtcNow),"MANUAL_DEV",r.ValorPago);}

